 63	/// The newest commit whose manifest holds `version` while its parent's does not.
 64	fn commit_setting_version(
 65	    git: &GitAccess<'_>,
 66	    manifest: &ManifestDecl,
 67	    version: &str,
 68	) -> Result<Option<String>, GraphError> {
 69	    for commit in git
 70	        .commits_since(None, std::slice::from_ref(&manifest.path))?
 71	        .iter()
 72	        .take(HISTORY_LIMIT)
 73	    {
 74	        let sha = commit.sha.as_str();
 75	        if version_at(git, sha, manifest)?.as_deref() != Some(version) {
 76	            continue;
 77	        }
 78	        // A root commit has no parent, so the version was set there.
 79	        let parent = version_at(git, &format!("{sha}^"), manifest).unwrap_or(None);
 80	        if parent.as_deref() != Some(version) {
 81	            return Ok(Some(sha.to_owned()));
 82	        }
 83	    }
 84	    Ok(None)
 85	}
